static inline dl_LLi *dl_LLi_share(dl_LLi *l) { if (l) dan_hdr_share(&l->h); return l; }
static inline void dl_LLi_release(dl_LLi *l) { if (l) dan_hdr_release(&l->h, dl_LLi_destroy); }
static inline void dl_LLi_give(dl_LLi *l) { if (l) dan_hdr_give(&l->h, dl_LLi_destroy); }

